import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query'
import { Link, createFileRoute, notFound } from '@tanstack/react-router'
import { useEffect, useRef, useState } from 'react'
import ReactMarkdown from 'react-markdown'
import {
  ChatQueryError,
  answerChat,
  fetchChat,
  sendChatMessage,
  type ChatScope,
} from '../../../../../lib/chat-queries'
import { Route as ScopeRoute } from '../../route'

export const Route = createFileRoute('/$type/$slug/chat/$chatId/')({ component: ChatPage })

type Conversation = Awaited<ReturnType<typeof fetchChat>>['data']
type ChatMessage = Conversation['messages'][number]
type Citation = ChatMessage['citations'][number]

function ChatPage() {
  const { chatId } = Route.useParams()
  // Remount per chat so answer and follow-up state never leaks between conversations.
  return <ChatConversation key={chatId} chatId={chatId} />
}

function ChatConversation({ chatId }: { chatId: string }) {
  const { type, slug } = Route.useParams()
  const { fund, portco } = ScopeRoute.useLoaderData()
  const scope: ChatScope = { fundId: fund.id, portcoId: portco?.id }
  const queryClient = useQueryClient()
  const chatKey = ['chat', chatId, scope.fundId, scope.portcoId ?? null]
  const [draft, setDraft] = useState('')
  const autoAnswered = useRef(new Set<string>())
  const endOfThread = useRef<HTMLDivElement>(null)

  const chat = useQuery({ queryKey: chatKey, queryFn: () => fetchChat(scope, chatId) })

  const refreshConversation = async () => {
    await Promise.all([
      queryClient.invalidateQueries({ queryKey: chatKey }),
      queryClient.invalidateQueries({ queryKey: ['chats', scope.fundId, scope.portcoId ?? null] }),
    ])
  }

  const answer = useMutation({
    mutationFn: () => answerChat(scope, chatId),
    onSettled: refreshConversation,
  })
  const followUp = useMutation({
    mutationFn: (content: string) => sendChatMessage(scope, chatId, content),
    onMutate: () => {
      answer.reset()
      setDraft('')
    },
    onError: async (_error, content) => {
      await refreshConversation()
      // The question is saved before answering; only unsaved text goes back into the box.
      const latest = queryClient
        .getQueryData<Awaited<ReturnType<typeof fetchChat>>>(chatKey)
        ?.data.messages.at(-1)
      if (latest?.role !== 'user' || latest.content !== content.trim()) setDraft(content)
      // A saved question whose answer just failed waits for an explicit retry.
      else autoAnswered.current.add(latest.id)
    },
    onSettled: async (_data, error) => {
      if (!error) await refreshConversation()
    },
  })

  const messages = chat.data?.data.messages ?? []
  const unanswered = messages.at(-1)?.role === 'user' ? messages.at(-1) : undefined

  useEffect(() => {
    // A new chat, a reload after an interrupted answer, or a question added elsewhere is answered once.
    if (!unanswered || autoAnswered.current.has(unanswered.id)) return
    if (answer.isPending || followUp.isPending) return
    autoAnswered.current.add(unanswered.id)
    answer.mutate()
  }, [unanswered, answer, followUp])

  useEffect(() => {
    endOfThread.current?.scrollIntoView({ block: 'end', behavior: 'smooth' })
  }, [messages.length, followUp.isPending])

  if (chat.isPending) return <ChatState>Loading conversation…</ChatState>
  if (chat.isError) {
    if (chat.error instanceof ChatQueryError && chat.error.status === 404) throw notFound()
    return <ChatState error>{chat.error.message}</ChatState>
  }
  const conversation = chat.data.data
  const answering = answer.isPending || followUp.isPending
  const answerFailure = unanswered && !answering ? (answer.error ?? followUp.error) : null
  const composerFailure = !unanswered && !followUp.isPending ? followUp.error : null
  const canSend = !unanswered && !answering
  // A refetch during sending can already include the saved question; don't show it twice.
  const showSendingQuestion =
    followUp.isPending && unanswered?.content !== followUp.variables.trim()

  const submit = () => {
    const content = draft.trim()
    if (content && canSend) followUp.mutate(content)
  }

  return (
    <main className="mx-auto flex min-h-full w-[min(800px,calc(100%-40px))] flex-col py-12 max-[720px]:w-full max-[720px]:px-5 max-[720px]:py-6">
      <header className="border-b border-rule pb-6">
        <p className="m-0 text-[0.83rem] text-muted">
          <Link
            className="underline decoration-rule underline-offset-[3px]"
            to="/$type/$slug"
            params={{ type, slug }}
          >
            {portco?.name ?? fund.name}
          </Link>
        </p>
        <h1 className="my-4 font-serif text-3xl font-normal tracking-[-0.03em]">
          {conversation.title ?? 'Conversation'}
        </h1>
        <p className="m-0 text-[0.82rem] text-muted">
          {portco ? 'Portfolio company scope' : 'Fund-wide scope'}
        </p>
      </header>
      <ol className="m-0 grid list-none gap-7 p-0 py-8" aria-live="polite">
        {conversation.messages.map((message) => (
          <MessageItem key={message.id} message={message}>
            {message.id === unanswered?.id ? (
              <AnswerStatus
                answering={answering}
                failure={answerFailure}
                onRetry={() => {
                  followUp.reset()
                  answer.mutate()
                }}
              />
            ) : null}
          </MessageItem>
        ))}
        {showSendingQuestion ? (
          <MessageItem message={{ id: 'sending', role: 'user', content: followUp.variables }}>
            <AnswerStatus answering failure={null} onRetry={() => undefined} />
          </MessageItem>
        ) : null}
      </ol>
      <div ref={endOfThread} />
      <form
        className="mt-auto border-t border-rule pt-5"
        onSubmit={(event) => {
          event.preventDefault()
          submit()
        }}
      >
        <label className="grid gap-2" htmlFor="follow-up-message">
          <span className="text-[0.9rem] font-semibold">Ask a follow-up</span>
          <textarea
            id="follow-up-message"
            rows={3}
            value={draft}
            onChange={(event) => setDraft(event.target.value)}
            onKeyDown={(event) => {
              if (event.key === 'Enter' && !event.shiftKey && !event.nativeEvent.isComposing) {
                event.preventDefault()
                submit()
              }
            }}
            disabled={!canSend}
            placeholder={
              unanswered
                ? 'Waiting for an answer to the last question…'
                : 'What else should we look into?'
            }
            className="w-full resize-y rounded-none border border-rule bg-card p-3 font-inherit text-ink disabled:cursor-not-allowed disabled:opacity-70"
          />
        </label>
        {composerFailure ? (
          <p className="mt-2 text-sm text-failure" role="alert">
            {composerFailure instanceof ChatQueryError && composerFailure.status === 400
              ? 'That message could not be sent. Check its length and try again.'
              : 'Your message was not sent. Try again.'}
          </p>
        ) : null}
        <div className="mt-3 flex items-center justify-between gap-4">
          <p className="m-0 text-[0.76rem] text-muted">
            Answers only use documents in this scope. Enter to send, Shift+Enter for a new line.
          </p>
          <button
            type="submit"
            disabled={!draft.trim() || !canSend}
            className="border border-accent bg-accent px-3 py-[9px] text-[0.84rem] text-white disabled:cursor-not-allowed disabled:opacity-55"
          >
            {followUp.isPending ? 'Sending…' : 'Send'}
          </button>
        </div>
      </form>
    </main>
  )
}

function MessageItem({
  message,
  children,
}: {
  message: Pick<ChatMessage, 'id' | 'role' | 'content'> & { citations?: Citation[] }
  children?: React.ReactNode
}) {
  const isAssistant = message.role === 'assistant'
  return (
    <li
      className="max-w-[720px] border-l-2 pl-4"
      style={{ borderColor: isAssistant ? 'var(--color-accent)' : 'var(--color-rule)' }}
    >
      <p className="m-0 mb-2 text-[0.76rem] font-semibold text-muted">
        {isAssistant ? 'Second Brain' : 'You'}
      </p>
      {isAssistant ? (
        <AssistantAnswer
          messageId={message.id}
          content={message.content}
          citations={message.citations ?? []}
        />
      ) : (
        <p className="m-0 whitespace-pre-wrap text-[0.96rem] leading-[1.7] text-ink">
          {message.content}
        </p>
      )}
      {children}
    </li>
  )
}

function AnswerStatus({
  answering,
  failure,
  onRetry,
}: {
  answering: boolean
  failure: Error | null
  onRetry: () => void
}) {
  if (answering) {
    return (
      <p className="mt-3 text-[0.8rem] text-muted" role="status">
        Searching the documents and drafting an answer…
      </p>
    )
  }
  if (!failure) return null
  return (
    <div
      className="mt-3 flex flex-wrap items-center gap-3 border-l-2 border-failure bg-card px-3 py-2"
      role="alert"
    >
      <p className="m-0 text-[0.82rem] text-failure">{failureMessage(failure)}</p>
      <button
        type="button"
        onClick={onRetry}
        className="border border-ink px-2.5 py-1 text-[0.8rem] text-ink hover:border-accent hover:text-accent"
      >
        Retry
      </button>
    </div>
  )
}

const citationMarker = /\[(\d+)\]/g

function AssistantAnswer({
  messageId,
  content,
  citations,
}: {
  messageId: string
  content: string
  citations: Citation[]
}) {
  const [openSources, setOpenSources] = useState<Set<number>>(() => new Set())
  const sourceId = (number: number) => `source-${messageId}-${number}`

  const toggleSource = (number: number) =>
    setOpenSources((current) => {
      const next = new Set(current)
      if (next.has(number)) next.delete(number)
      else next.add(number)
      return next
    })

  const revealSource = (number: number) => {
    setOpenSources((current) => new Set(current).add(number))
    const target = document.getElementById(sourceId(number))
    target?.scrollIntoView({ block: 'nearest', behavior: 'smooth' })
    target?.querySelector('button')?.focus({ preventScroll: true })
  }

  // Markers that match a stored citation become links; anything else stays as plain text.
  const linkedContent = content.replace(citationMarker, (marker, value: string) => {
    const number = Number(value)
    return number >= 1 && number <= citations.length
      ? `[\\[${number}\\]](#${sourceId(number)})`
      : marker
  })

  return (
    <>
      <div className="grid gap-3 text-[0.96rem] leading-[1.7] text-ink">
        <ReactMarkdown
          components={{
            p: ({ children }) => <p className="m-0">{children}</p>,
            ul: ({ children }) => <ul className="m-0 list-disc pl-6">{children}</ul>,
            ol: ({ children }) => <ol className="m-0 list-decimal pl-6">{children}</ol>,
            a: ({ children, href }) => {
              const number = href?.startsWith(`#source-${messageId}-`)
                ? Number(href.split('-').at(-1))
                : null
              if (!number) {
                return (
                  <a className="text-accent underline" href={href}>
                    {children}
                  </a>
                )
              }
              const citation = citations[number - 1]
              return (
                <button
                  type="button"
                  onClick={() => revealSource(number)}
                  aria-label={`Source ${number}: ${citation?.documentTitle ?? 'document'}`}
                  className="mx-px align-super text-[0.7rem] font-semibold text-accent hover:underline"
                >
                  {children}
                </button>
              )
            },
          }}
        >
          {linkedContent}
        </ReactMarkdown>
      </div>
      {citations.length > 0 ? (
        <aside className="mt-4 border-t border-rule pt-3" aria-label="Sources">
          <p className="m-0 text-[0.72rem] font-semibold text-muted">
            Sources ({citations.length})
          </p>
          <ol className="m-0 mt-2 grid list-none gap-1 p-0">
            {citations.map((citation, index) => {
              const number = index + 1
              const open = openSources.has(number)
              return (
                <li key={citation.chunkId} id={sourceId(number)}>
                  <button
                    type="button"
                    aria-expanded={open}
                    aria-controls={`${sourceId(number)}-excerpt`}
                    onClick={() => toggleSource(number)}
                    className="grid w-full grid-cols-[2rem_1fr_auto] items-baseline gap-2 py-1 text-left text-[0.8rem] hover:text-accent"
                  >
                    <span className="font-semibold text-accent">[{number}]</span>
                    <span className="min-w-0">
                      <span className="text-ink">{citation.documentTitle}</span>
                      <SourceLocation citation={citation} />
                    </span>
                    <span className="text-[0.72rem] text-muted" aria-hidden>
                      {open ? 'Hide' : 'Show'}
                    </span>
                  </button>
                  {open ? (
                    <blockquote
                      id={`${sourceId(number)}-excerpt`}
                      className="m-0 mb-2 ml-8 whitespace-pre-wrap border-l-2 border-rule bg-card px-3 py-2 text-[0.8rem] leading-[1.55] text-ink"
                    >
                      {citation.excerpt}
                    </blockquote>
                  ) : null}
                </li>
              )
            })}
          </ol>
        </aside>
      ) : null}
    </>
  )
}

function SourceLocation({ citation }: { citation: Citation }) {
  const section = citation.headingPath.join(' › ')
  const lines =
    citation.startLine !== null
      ? citation.endLine !== null && citation.endLine !== citation.startLine
        ? `Lines ${citation.startLine}–${citation.endLine}`
        : `Line ${citation.startLine}`
      : null
  const details = [section, lines].filter(Boolean)
  if (!details.length) return null
  return <span className="text-muted"> · {details.join(' · ')}</span>
}

function failureMessage(error: Error) {
  if (error instanceof ChatQueryError) {
    if (error.status === 503) {
      return 'The answer service is unavailable right now. Your question is saved; retry in a moment.'
    }
    if (error.status === 409) return 'This conversation changed elsewhere. Retry to continue.'
  }
  return 'Something went wrong while answering. Retry to try again.'
}

function ChatState({ children, error = false }: { children: React.ReactNode; error?: boolean }) {
  return (
    <main className="mx-auto w-[min(800px,calc(100%-40px))] py-12 text-muted max-[720px]:w-full max-[720px]:px-5 max-[720px]:py-6">
      <p className={error ? 'text-failure' : undefined}>{children}</p>
    </main>
  )
}

import { useState, type DragEvent } from 'react'
import { useMutation, useQuery, useQueryClient } from '@tanstack/react-query'
import ReactMarkdown from 'react-markdown'
import { ScopeSelect, type ScopeSelection } from '../../components/scope-select'
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
  AlertDialogTrigger,
} from '../../components/ui/alert-dialog'
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from '../../components/ui/dialog'
import { api } from '../../lib/api'
import { cn } from '../../lib/utils'

export type DocumentScope = {
  fundId: string
  portcoId?: string | null
}

type DocumentListProps = {
  scope: DocumentScope
}

type DocumentImportProps = {
  scope: DocumentScope
}

const documentQueryKey = (scope: DocumentScope) => [
  'documents',
  scope.fundId,
  scope.portcoId ?? null,
]

async function fetchDocuments(scope: DocumentScope) {
  const response = await api.documents.$get({
    query: {
      fundId: scope.fundId,
      ...(scope.portcoId ? { portcoId: scope.portcoId } : {}),
    },
  })

  if (!response.ok) {
    throw new Error(`Could not load documents (status ${response.status}).`)
  }

  return response.json()
}

type DocumentListItem = Awaited<ReturnType<typeof fetchDocuments>>['data'][number]

function stripMarkdownFrontmatter(content: string) {
  return content.replace(/^\uFEFF?---\r?\n[\s\S]*?\r?\n---\r?\n?/, '')
}

async function fetchDocument(documentId: string, scope: DocumentScope) {
  const response = await api.documents[':documentId'].$get({
    param: { documentId },
    query: { fundId: scope.fundId, ...(scope.portcoId ? { portcoId: scope.portcoId } : {}) },
  })
  if (!response.ok) throw new Error(`Could not load document (status ${response.status}).`)
  return response.json()
}

/** Lists the documents in a fund-wide or portfolio-company scope. */
export function DocumentList({ scope }: DocumentListProps) {
  const [selectedDocument, setSelectedDocument] = useState<DocumentListItem | null>(null)
  const documents = useQuery({
    queryKey: documentQueryKey(scope),
    queryFn: () => fetchDocuments(scope),
  })

  if (documents.isPending)
    return <p className="mt-16 border-t border-rule py-5 text-muted">Loading documents…</p>
  if (documents.isError)
    return <p className="mt-16 border-t border-rule py-5 text-failure">{documents.error.message}</p>

  if (documents.data.data.length === 0) {
    return (
      <p className="border-t border-rule py-5 text-[0.92rem] text-muted">
        No documents have been imported into this scope.
      </p>
    )
  }

  return (
    <>
      <div className="overflow-x-auto border-t border-rule">
        <table className="min-w-[620px] w-full border-collapse text-left">
          <thead>
            <tr>
              <th
                className="border-b border-rule py-3 pr-4 text-[0.73rem] font-semibold uppercase tracking-[0.03em] text-muted"
                scope="col"
              >
                Document
              </th>
              <th
                className="border-b border-rule py-3 pr-4 text-[0.73rem] font-semibold uppercase tracking-[0.03em] text-muted"
                scope="col"
              >
                Scope
              </th>
              <th
                className="border-b border-rule py-3 pr-4 text-[0.73rem] font-semibold uppercase tracking-[0.03em] text-muted"
                scope="col"
              >
                Imported
              </th>
              <th
                className="border-b border-rule py-3 pr-0 text-[0.73rem] font-semibold uppercase tracking-[0.03em] text-muted"
                scope="col"
              >
                Status
              </th>
            </tr>
          </thead>
          <tbody>
            {documents.data.data.map((document) => (
              <tr key={document.id}>
                <td className="border-b border-rule py-4 pr-4 text-[0.84rem] text-muted">
                  <button
                    type="button"
                    className="block cursor-pointer text-left font-serif text-[1.05rem] font-normal text-ink underline decoration-rule underline-offset-4 hover:text-accent"
                    onClick={() => setSelectedDocument(document)}
                  >
                    {document.title}
                  </button>
                  <small className="mt-[3px] block">{document.filename}</small>
                </td>
                <td className="border-b border-rule py-4 pr-4 text-[0.84rem] text-muted">
                  {document.portcoId ? 'Portfolio company' : 'Fund-wide'}
                </td>
                <td className="border-b border-rule py-4 pr-4 text-[0.84rem] text-muted">
                  {new Intl.DateTimeFormat(undefined, { dateStyle: 'medium' }).format(
                    new Date(document.createdAt)
                  )}
                </td>
                <td className="border-b border-rule py-4 pr-0 text-[0.84rem] text-muted">
                  <span
                    className={cn(
                      'text-[0.76rem] capitalize',
                      document.status === 'completed' && 'text-accent',
                      document.status === 'failed' && 'text-failure'
                    )}
                  >
                    {document.status}
                  </span>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
      {selectedDocument ? (
        <DocumentViewer
          document={selectedDocument}
          scope={scope}
          onClose={() => setSelectedDocument(null)}
        />
      ) : null}
    </>
  )
}

function DocumentViewer({
  document,
  scope,
  onClose,
}: {
  document: DocumentListItem
  scope: DocumentScope
  onClose: () => void
}) {
  const queryClient = useQueryClient()
  const [confirmOpen, setConfirmOpen] = useState(false)
  const detail = useQuery({
    queryKey: ['document', document.id, scope.fundId, scope.portcoId ?? null],
    queryFn: () => fetchDocument(document.id, scope),
  })
  const deleteDocument = useMutation({
    mutationFn: async () => {
      const response = await api.documents[':documentId'].$delete({
        param: { documentId: document.id },
        query: {
          fundId: scope.fundId,
          ...(scope.portcoId ? { portcoId: scope.portcoId } : {}),
        },
      })
      if (!response.ok) {
        const body = await response.json().catch(() => null)
        const message =
          body && 'error' in body
            ? body.error
            : `Could not delete document (status ${response.status}).`
        throw new Error(message)
      }
    },
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: ['documents', scope.fundId] })
      queryClient.removeQueries({ queryKey: ['document', document.id] })
      setConfirmOpen(false)
      onClose()
    },
  })

  return (
    <Dialog open onOpenChange={(open) => !open && onClose()}>
      <DialogContent className="h-[min(900px,calc(100dvh-2rem))] max-h-[calc(100dvh-2rem)] max-w-[calc(100%-2rem)]! overflow-hidden rounded-none! border-rule! bg-paper! text-ink sm:max-w-5xl! grid-rows-[auto_minmax(0,1fr)_auto]">
        <DialogHeader>
          <DialogTitle className="font-serif text-[1.7rem] font-normal tracking-[-0.03em]">
            {document.title}
          </DialogTitle>
          <DialogDescription className="flex flex-wrap gap-x-3 gap-y-1 text-[0.78rem] text-muted">
            <span>{document.filename}</span>
            <span className="capitalize">{document.status}</span>
          </DialogDescription>
        </DialogHeader>
        <div className="min-h-0 overflow-y-auto overscroll-contain border-t border-rule pt-5 pr-2">
          {detail.isPending ? <p className="text-muted">Loading document…</p> : null}
          {detail.isError ? <p className="text-failure">{detail.error.message}</p> : null}
          {detail.data ? (
            detail.data.data.mimeType === 'text/markdown' ? (
              <article className="mx-auto max-w-[800px] space-y-4 text-[0.96rem] leading-[1.7] text-ink">
                <ReactMarkdown
                  components={{
                    h1: ({ children }) => (
                      <h1 className="font-serif text-3xl font-normal">{children}</h1>
                    ),
                    h2: ({ children }) => (
                      <h2 className="font-serif text-2xl font-normal">{children}</h2>
                    ),
                    h3: ({ children }) => (
                      <h3 className="font-serif text-xl font-normal">{children}</h3>
                    ),
                    a: ({ children, href }) => (
                      <a className="text-accent underline" href={href}>
                        {children}
                      </a>
                    ),
                    ul: ({ children }) => <ul className="list-disc pl-6">{children}</ul>,
                    ol: ({ children }) => <ol className="list-decimal pl-6">{children}</ol>,
                    blockquote: ({ children }) => (
                      <blockquote className="border-l-2 border-accent pl-4 text-muted">
                        {children}
                      </blockquote>
                    ),
                  }}
                >
                  {stripMarkdownFrontmatter(detail.data.data.content)}
                </ReactMarkdown>
              </article>
            ) : (
              <pre className="mx-auto max-w-[800px] whitespace-pre-wrap font-sans text-[0.96rem] leading-[1.7] text-ink">
                {detail.data.data.content}
              </pre>
            )
          ) : null}
        </div>
        <div className="flex justify-end border-t border-rule pt-4">
          <AlertDialog open={confirmOpen} onOpenChange={setConfirmOpen}>
            <AlertDialogTrigger asChild>
              <button
                type="button"
                className="cursor-pointer text-[0.78rem] text-failure underline underline-offset-4"
              >
                Delete document
              </button>
            </AlertDialogTrigger>
            <AlertDialogContent className="rounded-none border-rule bg-paper text-ink">
              <AlertDialogHeader>
                <AlertDialogTitle className="font-serif text-xl font-normal">
                  Delete “{document.title}”?
                </AlertDialogTitle>
                <AlertDialogDescription className="leading-[1.5] text-muted">
                  This removes the source document and its processed chunks. This action cannot be
                  undone.
                </AlertDialogDescription>
              </AlertDialogHeader>
              {deleteDocument.isError ? (
                <p className="text-sm text-failure">{deleteDocument.error.message}</p>
              ) : null}
              <AlertDialogFooter>
                <AlertDialogCancel disabled={deleteDocument.isPending}>Cancel</AlertDialogCancel>
                <AlertDialogAction
                  onClick={(event) => {
                    event.preventDefault()
                    deleteDocument.mutate()
                  }}
                  disabled={deleteDocument.isPending}
                >
                  {deleteDocument.isPending ? 'Deleting…' : 'Delete document'}
                </AlertDialogAction>
              </AlertDialogFooter>
            </AlertDialogContent>
          </AlertDialog>
        </div>
      </DialogContent>
    </Dialog>
  )
}

/** Imports a text or Markdown document, keeping the selected scope explicit. */
export function DocumentImport({ scope }: DocumentImportProps) {
  const queryClient = useQueryClient()
  const [open, setOpen] = useState(false)
  const [file, setFile] = useState<File | null>(null)
  const [title, setTitle] = useState('')
  const [targetScope, setTargetScope] = useState<DocumentScope>(scope)

  const importDocument = useMutation({
    mutationFn: async () => {
      if (!file) throw new Error('Choose a document before importing.')

      const response = await api.documents.$post({
        form: {
          file,
          fundId: targetScope.fundId,
          ...(targetScope.portcoId ? { portcoId: targetScope.portcoId } : {}),
          ...(title.trim() ? { title: title.trim() } : {}),
        },
      })

      if (!response.ok) {
        const body = await response.json().catch(() => null)
        const message =
          body && 'error' in body ? body.error : `Import failed (status ${response.status}).`
        throw new Error(message)
      }
    },
    onSuccess: async () => {
      await queryClient.invalidateQueries({ queryKey: ['documents', scope.fundId] })
      setFile(null)
      setTitle('')
      setTargetScope(scope)
      setOpen(false)
    },
  })

  function chooseFile(candidate: File | undefined) {
    if (!candidate) return
    setFile(candidate)
    importDocument.reset()
  }

  function handleDrop(event: DragEvent<HTMLLabelElement>) {
    event.preventDefault()
    chooseFile(event.dataTransfer.files[0])
  }

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>
        <button
          type="button"
          className="cursor-pointer border border-accent bg-accent px-3 py-[9px] text-[0.84rem] text-white"
        >
          Import document
        </button>
      </DialogTrigger>
      <DialogContent className="max-w-[570px] rounded-none! border-rule! bg-paper! text-ink">
        <DialogHeader>
          <DialogTitle className="font-serif text-[1.7rem] font-normal tracking-[-0.03em]">
            Import a document
          </DialogTitle>
          <DialogDescription className="leading-[1.5] text-muted">
            Add Markdown or plain text to the evidence available in this scope.
          </DialogDescription>
        </DialogHeader>
        <form
          className="grid gap-5"
          onSubmit={(event) => {
            event.preventDefault()
            importDocument.mutate()
          }}
        >
          {scope.portcoId ? (
            <p className="border-l-2 border-accent pl-2.5 text-[0.84rem] leading-[1.5] text-muted">
              This import stays within the current portfolio company.
            </p>
          ) : (
            <ScopeSelect
              fundId={scope.fundId}
              portcoId={targetScope.portcoId}
              onScopeChange={(selection: ScopeSelection) =>
                setTargetScope({ fundId: scope.fundId, portcoId: selection.portcoId })
              }
              disabled={importDocument.isPending}
            />
          )}
          <label className="grid gap-[7px]">
            <span className="text-[0.82rem] font-semibold">
              Title <em className="text-[0.75rem] font-normal not-italic text-muted">optional</em>
            </span>
            <input
              className="rounded-none border border-rule bg-card p-[10px_11px] font-[inherit] text-ink"
              value={title}
              onChange={(event) => setTitle(event.target.value)}
              placeholder={file?.name ?? 'Use the filename'}
              disabled={importDocument.isPending}
            />
          </label>
          <label
            className="grid min-h-[154px] cursor-pointer place-items-center border border-dashed border-muted p-5 text-center text-muted hover:border-accent hover:text-accent"
            htmlFor="document-file"
            onDragOver={(event) => event.preventDefault()}
            onDrop={handleDrop}
          >
            <input
              className="sr-only"
              id="document-file"
              type="file"
              accept=".md,.markdown,.txt,text/markdown,text/plain"
              onChange={(event) => chooseFile(event.target.files?.[0])}
              disabled={importDocument.isPending}
            />
            <strong className="font-serif text-[1.25rem] font-normal text-ink">
              {file ? file.name : 'Drop a document here'}
            </strong>
            <span className="text-[0.78rem]">
              {file
                ? `${Math.ceil(file.size / 1024)} KB · choose another file`
                : 'or choose a file · Markdown or text · up to 5 MB'}
            </span>
          </label>
          {importDocument.isError ? (
            <p className="-mt-1 text-[0.84rem] text-failure">{importDocument.error.message}</p>
          ) : null}
          <div className="flex justify-end">
            <button
              type="submit"
              className="cursor-pointer border border-accent bg-accent px-3 py-[9px] text-[0.84rem] text-white disabled:cursor-wait disabled:opacity-55"
              disabled={!file || importDocument.isPending}
            >
              {importDocument.isPending ? 'Importing…' : 'Import document'}
            </button>
          </div>
        </form>
      </DialogContent>
    </Dialog>
  )
}

